/**
 * Sina's handwritten signature, traced from the scan into closed outlines and grouped into the six
 * strokes the pen makes, in writing order. Coordinates are viewBox units of the source artboard
 * (`0 0 1493 481`).
 *
 * `Signature` fills every outline at once (even-odd, so counters stay open). `SignatureDraw` writes
 * the name: each outline is drawn along both of its sides from where the pen starts to where it
 * lifts, while the pen passes over it, and the stroke's ink fills in behind.
 */

/** Cropped to the ink, so a height class sizes the mark. */
export const SIGNATURE_VIEWBOX = '16 16 1462 450'

export interface SignatureContour {
  /** Closed outline as `x y x y …`, starting at the tip the pen starts from. */
  points: string
  /**
   * Index of the point where the pen lifts: the outline is drawn as its two sides, both running
   * from the first point to this one. Absent on the O, a loop the pen goes round: it is drawn once,
   * counter-clockwise from the top.
   */
  tip?: number
}

export interface SignatureStroke {
  name: string
  /** When the pen is on this stroke, as a share of the whole write (0–1). */
  pen: readonly [number, number]
  /** The stroke's outline, then the counters inside it. */
  contours: readonly SignatureContour[]
}

