/** Every outline as one even-odd path: the finished mark. */
export const SIGNATURE_PATH = SIGNATURE_STROKES.flatMap((stroke) => stroke.contours)
  .map(({ points }) => `M${points}Z`)
  .join('')

export interface DrawnLine {
  /** One side of an outline, or a whole loop. */
  d: string
  /** Pen positions (0–1) between which this line is drawn. */
  from: number
  to: number
}

export interface DrawnStroke {
  name: string
  /** The stroke's outlines as one even-odd path, filled once the pen has passed. */
  ink: string
  /** Pen position at which the pen leaves the stroke. */
  inkAt: number
  lines: DrawnLine[]
}

const round = (value: number) => Math.round(value * 1000) / 1000

/**
 * The geometry `SignatureDraw` animates. The pen crosses each stroke from left to right, so an
 * outline — the stroke's own, or a counter's — is drawn while the pen passes over its extent.
 */
export function drawSignature(
  strokes: readonly SignatureStroke[] = SIGNATURE_STROKES,
): DrawnStroke[] {
  return strokes.map(({ contours, name, pen: [start, end] }) => {
    const outlines = contours.map(({ points, tip }) => {
      const xy = points.split(' ').map(Number)
      const pts: Array<[number, number]> = []
      for (let i = 0; i < xy.length; i += 2) pts.push([xy[i]!, xy[i + 1]!])
      return { points, pts, tip, xs: pts.map(([x]) => x) }
    })
    const left = Math.min(...outlines.flatMap(({ xs }) => xs))
    const span = Math.max(...outlines.flatMap(({ xs }) => xs)) - left
    const at = (x: number) => round(start + ((x - left) / span) * (end - start))
    const polyline = (pts: Array<[number, number]>) => `M${pts.map((p) => p.join(' ')).join(' ')}`

    return {
      name,
      ink: contours.map(({ points }) => `M${points}Z`).join(''),
      inkAt: end,
      lines: outlines.flatMap(({ points, pts, tip, xs }) => {
        const from = at(Math.min(...xs))
        const to = at(Math.max(...xs))
        if (tip === undefined) return [{ d: `M${points}Z`, from, to }]
        return [pts.slice(0, tip + 1), [pts[0]!, ...pts.slice(tip).reverse()]].map((side) => ({
          d: polyline(side),
          from,
          to,
        }))
      }),
    }
  })
}
